code.C:
#include <stdio.h>
int main() {
    char s[20]; if (scanf("%s", s) != 1) return 0;
    long long ans = 0;
    for (int i = 0; s[i]; i++) ans = ans * 26 + (s[i] - 'A' + 1);
    printf("%lld\n", ans);
    return 0;
}

