        cout << ans << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            String s = sc.next();
            long ans = 0;
            for (char c : s.toCharArray()) ans = ans * 26 + (c - 'A' + 1);
            System.out.println(ans);
        }
    }
}

